package app.swarsetu.stt.sravaani

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import java.util.Base64

/**
 * Pins [SravaaniFeaturizer] to the OFFICIAL SraVaani 0.5 featurization.
 *
 * Golden vectors are generated by `scripts/sravaani/gen_android_assets.py` from the official
 * artifact's math (preemph -> stft(center=True) -> |X|^2 -> mel -> log -> per-feature mean/std
 * over all valid frames), serialized as base64 f32-LE in
 * `src/test/resources/sravaani/golden_features.json`. Tolerance 1e-3 absolute: the desktop
 * reference-vs-graph gate measured 4.4e-4 max, all of it fp32 reassociation.
 *
 * The probe signal is 26880 samples = 168 valid frames, so the official chunk-0 block
 * (pec 9 + chunk 112) AND the chunk-1 cache slice [112-9, 112) are both fully materialized.
 */
class SravaaniFeaturizerGoldenTest {

    private lateinit var golden: Map<String, String>
    private lateinit var tables: SravaaniTables

    @Before
    fun load() {
        val text =
            javaClass.getResourceAsStream("/sravaani/golden_features.json")!!
                .readBytes().decodeToString()
        golden = Json.parseToJsonElement(text).jsonObject
            .mapValues { (_, v) -> v.toString().trim('\"') }
        tables = javaClass.getResourceAsStream("/sravaani/tables.bin")!!.use {
            SravaaniTables.read(it)
        }
    }

    private fun f32(key: String): FloatArray =
        Base64.getDecoder().decode(golden.getValue(key)).let { bytes ->
            val buf = java.nio.ByteBuffer.wrap(bytes).order(java.nio.ByteOrder.LITTLE_ENDIAN)
            FloatArray(bytes.size / 4) { buf.float }
        }

    private fun intKey(key: String): Int = golden.getValue(key).trim('\"').toInt()

    @Test
    fun `normalized frames match official chunk values`() {
        val feat = SravaaniFeaturizer(tables)
        val signal = f32("signal_b64")
        val seqLen = intKey("seq_len")
        assertEquals(168, seqLen)

        feat.push(signal, signal.size)
        assertEquals(seqLen.toLong(), feat.producedFrames)

        val chunk0 = f32("chunk0_b64") // (121, 128): pec zero-pad + frames [0, 112) normalized
        val frame = FloatArray(tables.melBins)
        var maxDiff = 0f
        // Chunk-0's 9 cache rows are pad_value 0.0 — compare the engine's step-0 assembly.
        val block = FloatArray(SravaaniStreamingState.CHUNK_FRAMES * tables.melBins)
        for (f in 0 until SravaaniStreamingState.CHUNK_SIZE) {
            feat.getNormalizedFrame(f.toLong(), frame)
            System.arraycopy(frame, 0, block, (9 + f) * tables.melBins, tables.melBins)
        }
        for (i in 0 until 9 * tables.melBins) {
            assertEquals(0.0f, block[i], 0f)
        }
        for (i in 9 * tables.melBins until block.size) {
            maxDiff = maxOf(maxDiff, kotlin.math.abs(chunk0[i] - block[i]))
        }
        assertTrue("chunk-0 max abs diff $maxDiff exceeds 1e-3", maxDiff <= 1e-3f)
    }

    @Test
    fun `chunk-1 pre-encode cache matches official re-normalized slice`() {
        val feat = SravaaniFeaturizer(tables)
        val signal = f32("signal_b64")
        feat.push(signal, signal.size)

        val chunk1Cache = f32("chunk1_cache_b64") // (9, 128): frames [103, 112) at final stats
        val frame = FloatArray(tables.melBins)
        var maxDiff = 0f
        for (f in 0 until 9) {
            feat.getNormalizedFrame(103L + f, frame)
            for (m in 0 until tables.melBins) {
                maxDiff = maxOf(maxDiff, kotlin.math.abs(chunk1Cache[f * tables.melBins + m] - frame[m]))
            }
        }
        assertTrue("chunk-1 cache max abs diff $maxDiff exceeds 1e-3", maxDiff <= 1e-3f)
    }

    @Test
    fun `chunk-size independence - incremental pushes equal one-shot`() {
        val signal = f32("signal_b64")

        val oneShot = SravaaniFeaturizer(tables)
        oneShot.push(signal, signal.size)

        val incremental = SravaaniFeaturizer(tables)
        var off = 0
        val steps = intArrayOf(1000, 160, 1600, 7, 3200, 1600, 13, 977)
        var s = 0
        while (off < signal.size) {
            val n = minOf(steps[s % steps.size], signal.size - off)
            incremental.push(signal.copyOfRange(off, off + n), n)
            off += n
            s++
        }
        assertEquals(oneShot.producedFrames, incremental.producedFrames)

        val a = FloatArray(tables.melBins)
        val b = FloatArray(tables.melBins)
        for (f in 0 until oneShot.producedFrames) {
            oneShot.getNormalizedFrame(f, a)
            incremental.getNormalizedFrame(f, b)
            assertTrue("frame $f diverges", a.contentEquals(b))
        }
    }

    @Test
    fun `seq_len matches official wavLen-hop criterion`() {
        val feat = SravaaniFeaturizer(tables)
        val signal = f32("signal_b64")
        feat.push(signal, signal.size)
        // Official: seq_len = wavLen // hop = 26880 // 160 = 168.
        assertEquals(168L, feat.producedFrames)
    }
}
